    mergeUtxo.push({
      tx: splitTxObj,
      vout: 2,
    });
    await expect(() =>
      mergeWithCallback(
        privateKey.publicKey,
        mergeUtxo,
        addr,
        fundingUtxo,
        privateKey.publicKey,
        ownerSignatureCallback,
        ownerSignatureCallback
      )
    ).rejects.toThrow("This function can only merge exactly 2 STAS tokens");
  });

  it("should fail with less than two merge utxos", async () => {
    let mergeUtxo = [
      {
        tx: splitTxObj,
        vout: 0,
      },
    ];
    await expect(() =>
      mergeWithCallback(
        privateKey.publicKey,
        mergeUtxo,
        addr,
        fundingUtxo,
        privateKey.publicKey,
        ownerSignatureCallback,
        ownerSignatureCallback
      )
    ).rejects.toThrow("This function can only merge exactly 2 STAS tokens");
  });

