      mergeWithCallback(
        privateKey.publicKey,
        getMergeUTxoDiffData(),
        addr,
        fundingUtxo,
        privateKey.publicKey,
        ownerSignatureCallback,
        ownerSignatureCallback
      )
    ).rejects.toThrow(
