async function getTransactions(address) {
  const url = `https://api.whatsonchain.com/v1/bsv/main/address/${address}/unspent`;

  let response;
  try {
    response = await axios({
      method: "get",
      url,
    });
  } catch (error) {
    console.log(error);
  }
  const txArray = [];
  response.data.forEach((data) => {
    if (data.value > 500 && data.value < 10000) {
      const obj = {
        txid: data.tx_hash,
        vout: data.tx_pos,
        satoshis: data.value,
      };
      txArray.push(obj);
    }
  });
  return txArray;
}

