  const url = `https://api.whatsonchain.com/v1/bsv/main/tx/hash/${txid}`;
  let response;
  try {
    response = await axios({
      method: "get",
      url,
    });
  } catch (err) {
    console.log(err);
  }

  return response.data;
}

